class Assign(object):
    """The ``Assign`` specifier type provides dictionary-like specification
    behavior, allowing you to map keys to values in the output structure.

    This is equivalent to using a Python dict literal as a glom spec, but
    provides a class-based interface for more complex scenarios.

    Args:
       mapping: A dictionary or mapping of keys to sub-specs. Each key
         becomes a field in the output dict, and each value is evaluated
         as a sub-spec against the target.

    Example:

      >>> target = {'a': 1, 'b': 2}
      >>> glom(target, Assign({'x': 'a', 'y': 'b'}))
      {'x': 1, 'y': 2}

    The ``assign()`` convenience function provides an alias for creating
    Assign instances:

      >>> assign({'x': 'a'}) == Assign({'x': 'a'})
      True

    """
    def __init__(self, mapping):
        self.mapping = mapping

    def glomit(self, target, scope):
        ret = {}
        for field, subspec in self.mapping.items():
            val = scope[glom](target, subspec, scope)
            if val is SKIP:
                continue
            if type(field) in (Spec, TType):
                field = scope[glom](target, field, scope)
            ret[field] = val
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.mapping)


def assign(mapping):
    """Convenience function to create an :class:`Assign` specifier.

    See :class:`Assign` for details.
    """
    return Assign(mapping)



